import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;

public class CacheProtection {
    private final RedisClient redis;

    // ==================== 穿透防护：布隆过滤器 + 空值缓存 ====================

    public <T> T getWithBloom(String bloomKey, String cacheKey, Supplier<T> loader) {
        // BF.MEXISTS 返回 0 → 一定不存在，直接返回 null，不查 DB
        long exists = redis.bfExists(bloomKey, cacheKey);
        if (exists == 0) return null;

        return getWithNullCache(cacheKey, loader);
    }

    private <T> T getWithNullCache(String key, Supplier<T> loader) {
        String cached = redis.get(key);
        if (cached != null) {
            return "NULL".equals(cached) ? null : decode(cached);
        }

        T value = loader.get();
        if (value == null) {
            // 空值缓存：短 TTL 防止同一无效 key 重复回源
            redis.setex(key, 60, "NULL");
            return null;
        }

        int ttl = 300 + ThreadLocalRandom.current().nextInt(60); // TTL 抖动 20%
        redis.setex(key, ttl, encode(value));
        return value;
    }

    // ==================== 击穿防护：互斥重建 ====================

    public <T> T getWithMutexRebuild(String key, Supplier<T> loader) {
        String cached = redis.get(key);
        if (cached != null) return decode(cached);

        String token = UUID.randomUUID().toString();
        String lockKey = "lock:rebuild:" + key;

        // SET lock:rebuild:<key> <token> NX PX 5000
        // NX 保证只有一个线程拿到锁，PX 防止持锁崩溃后死锁
        boolean locked = "OK".equals(
            redis.set(lockKey, token, "NX", "PX", 5000));

        if (locked) {
            try {
                // 二次检查：拿到锁后可能其他线程已重建
                cached = redis.get(key);
                if (cached != null) return decode(cached);

                T value = loader.get();
                int ttl = 300 + ThreadLocalRandom.current().nextInt(60);
                redis.setex(key, ttl, encode(value));
                return value;
            } finally {
                // Lua 原子释放：校验 token 防止误删他人锁
                redis.eval(
                    "if redis.call('get', KEYS[1]) == ARGV[1] then " +
                    "return redis.call('del', KEYS[1]) else return 0 end",
                    1, lockKey, token);
            }
        } else {
            // 拿不到锁：退避重试，避免惊群效应
            try {
                Thread.sleep(50 + ThreadLocalRandom.current().nextInt(50));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            return getWithMutexRebuild(key, loader);
        }
    }

    // ==================== 雪崩防护：TTL 抖动已在上面实现 ====================
    // TTL = base + random(0, base * 0.2)，同批 key 分散过期
    // 生产中还需配合：Caffeine 本地缓存 + Sentinel 限流降级
}
